from collections import *
from bisect import *
from math import *
import sys
input = sys.stdin.readline
t = int(input())
while t:
	t -= 1
	(h, q) = map(int, input().split())
	r = []
	for i in range(q):
		(tt, x, a) = map(int, input().split())
		r.append([tt, x, a, i])
	r.sort(key=lambda x: x[1])
	fr = [0 for i in range(q)]
	for i in range(q):
		slope1 = float('inf')
		slope2 = -float('inf')
		(x, y) = (r[i][1], r[i][2])
		if r[i][0] == 0:
			typ = 0
		else:
			typ = 1
		c = 0
		for j in range(i + 1, q):
			if typ == 0:
				try:
					cur = (y - r[j][2]) / (x - r[j][1])
				except:
					c += 1
					fr[r[j][3]] += 1
					continue
				if r[j][0] == 1:
					if slope1 > cur and cur > slope2:
						c += 1
						fr[r[j][3]] += 1
					slope1 = min(cur, slope1)
				else:
					if slope2 < cur and cur < slope1:
						c += 1
						fr[r[j][3]] += 1
					slope2 = max(cur, slope2)
			else:
				try:
					cur = (y - r[j][2]) / (x - r[j][1])
				except:
					c += 1
					fr[r[j][3]] += 1
					continue
				if r[j][0] == 1:
					if slope1 > cur and cur > slope2:
						c += 1
						fr[r[j][3]] += 1
					slope1 = min(cur, slope1)
				else:
					if slope2 < cur and cur < slope1:
						c += 1
						fr[r[j][3]] += 1
					slope2 = max(cur, slope2)
			if slope2 >= slope1:
				break
		fr[r[i][3]] += c
	print(*fr)
